from pathlib import Path
from datetime import datetime
from zoneinfo import ZoneInfo
from concurrent.futures import ThreadPoolExecutor,as_completed
import json,hashlib,requests
base=Path('reports/research/510300_industrial_same_title_original_carriers_v1')
e95=Path('reports/research/510300_industrial_native_official_search_source_v1')
def now():return datetime.now(ZoneInfo('Asia/Shanghai')).isoformat()
def readj(p):return json.loads(Path(p).read_text(encoding='utf-8-sig'))
proto=readj(base/'protocol.json');site=readj(base/'真实站点配置首次请求回执.json')
config=site['payload']['data']['tabs'][0]['combinConf'];assert config['status'] and config['combineField']=='MD5TITLE'
qs={r['economic_period']:r['qt'] for r in readj(e95/'protocol.json')['native_queries_fixed_before_requests']}
targets=[{'economic_period':g['economic_period'],'url':'https://api.so-gov.cn/query/combin','method':'POST','original_title':g['original_title'],'data':{'siteCode':'bm36000002','tab':'','qt':qs[g['economic_period']],'reference':g['reference'],'combinField':config['combineField'],'combinValue':g['original_md5Title']}} for g in proto['actual_same_title_groups']]
p=base/'原同标题合并列表真实请求前登记.json';assert not p.exists();p.write_text(json.dumps({'at':now(),'actual_original_site_configuration':config,'configuration_source_path':site['path'],'configuration_sha256':site['sha256'],'targets':targets,'default_first_page_no_adjustment':True,'one_request_per_original_group':True,'authentication':0,'new_fits_or_labels':0},ensure_ascii=False,indent=2),encoding='utf-8')
def fetch(t):
 out={**t,'started_at':now(),'attempt':1}
 try:
  r=requests.post(t['url'],data=t['data'],timeout=(10,30));p=base/(t['economic_period']+'_原同标题列表响应.json.txt');assert not p.exists();p.write_bytes(r.content)
  text=r.content.decode('utf-8-sig',errors='replace')
  try:payload=json.loads(text)
  except ValueError:payload=None
  out.update(status_code=r.status_code,path=p.as_posix(),sha256=hashlib.sha256(r.content).hexdigest(),bytes=len(r.content),payload=payload,full_text=text,status='PUBLIC_SAME_TITLE_JSON_CANDIDATE' if r.status_code==200 and isinstance(payload,dict) else 'UNKNOWN_PUBLIC_SAME_TITLE_RESPONSE')
 except Exception as e:out.update(status='REQUEST_FAILED_NO_RETRY',error_type=type(e).__name__,error=str(e))
 out['completed_at']=now();return out
rs=[]
with ThreadPoolExecutor(max_workers=2) as pool:
 for f in as_completed([pool.submit(fetch,t) for t in targets]):rs.append(f.result())
p=base/'两个实际原同标题列表首次取得回执.json';assert not p.exists();p.write_text(json.dumps({'at':now(),'requests':rs,'actual_public_list_requests':2,'authentication':0,'new_fits_or_labels':0},ensure_ascii=False,indent=2),encoding='utf-8')
for r in rs:print(json.dumps({'period':r['economic_period'],'status':r['status'],'payload_keys':list(r['payload']) if isinstance(r.get('payload'),dict) else None,'原响应前段':r.get('full_text','')[:2500]},ensure_ascii=False),flush=True)
